    title: "Notes on the everyday",
    category: "Digital / concept study",
    year: "2026",
    description: "An editorial home for the things worth paying attention to.",
    mark: "Notes.",
  },
];
export const sampleServices: readonly Studio01Service[] = [
  {
    id: "direction",
    title: "A clear direction.",
    description:
      "Find the idea at the centre of the work, and give the next decisions something to stand on.",
    deliverables: [
      "Positioning and story",
      "Creative direction",
      "A practical brief",
    ],
  },
  {
    id: "identity",
    title: "An identity with room to grow.",
    description:
