    ],
  },
  {
    id: "digital",
    title: "A good idea, out in the world.",
    description:
      "Thoughtful websites and digital experiences built around the people who will use them.",
    deliverables: [
      "Website and product design",
      "Component-driven implementation",
      "A considered handover",
    ],
  },
];
export function validateStudio(
  projects: readonly Studio01Project[],
  services: readonly Studio01Service[],
) {
  for (const items of [projects, services]) {
    const ids = new Set<string>();
    for (const item of items) {
      if (!/^[a-zA-Z0-9][a-zA-Z0-9_-]*$/.test(item.id) || ids.has(item.id))
        throw new RangeError("Studio items require unique anchor-safe IDs.");
      ids.add(item.id);
    }
  }
}
export function prepareStudioBrief(
  draft: Studio01Brief,
  services: readonly Studio01Service[],
  labels: Studio01Labels = defaultStudioLabels,
) {
  const brief = {
    name: draft.name.trim(),
    email: draft.email.trim(),
    serviceId: draft.serviceId,
    message: draft.message.trim(),
  };
  const errors: Partial<Record<keyof Studio01Brief, string>> = {};
  if (!brief.name) errors.name = labels.invalidName;
  if (!/^[^\s@]+@[^\s@]+$/.test(brief.email))
    errors.email = labels.invalidEmail;
  if (!services.some((service) => service.id === brief.serviceId))
    errors.serviceId = labels.invalidService;
  if (!brief.message) errors.message = labels.invalidMessage;
  return { brief: Object.keys(errors).length ? null : brief, errors };
}

.studio01 {
  --studio01-column-gap: var(--space-10);
  --studio01-section-gap: var(--space-12);
  background: var(--background-primary);
  color: var(--text-primary);
  font-family: var(--font-family-body);
  padding: var(--space-6) var(--container-padding-lg) var(--space-8);
}
.studio01 *,
.studio01 *::before,
.studio01 *::after {
  box-sizing: border-box;
}
.studio01 :is(h1, h2, h3, p, ul) {
  margin: 0;
}
.studio01-inner {
  max-width: var(--container-max-width);
  margin-inline: auto;
}
.studio01 a {
  color: inherit;
  text-underline-offset: var(--space-1);
}
.studio01 a:focus-visible {
  outline: var(--focus-ring-width) solid var(--focus-ring-color);
  outline-offset: var(--focus-ring-offset);
}
.studio01 :is(header, section) {
  scroll-margin-block-start: var(--space-8);
}
.studio01 .studio01-masthead {
  gap: var(--space-5);
  padding-block-end: var(--space-5);
  border-block-end: var(--border-width-thin) solid var(--border-default);
}
.studio01-brand {
  text-decoration: none;
  font-family: var(--font-family-display);
  font-size: var(--font-size-2xl);
  letter-spacing: var(--letter-spacing-tight);
}
.studio01-brand > span {
  color: var(--brand-primary);
}
.studio01-masthead nav {
  font-size: var(--typography-caption-size);
}
.studio01-masthead nav a {
  text-decoration: none;
}
.studio01-masthead nav a:hover {
  text-decoration: underline;
}
.studio01 .studio01-kicker {
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wider);
  font-weight: var(--font-weight-medium);
  line-height: var(--line-height-relaxed);
  color: var(--text-muted);
}
.studio01-hero {
  padding-block: var(--space-10);
}
.studio01-hero h1 {
  font-size: var(--typography-hero-size);
  letter-spacing: var(--typography-heading-letterspacing);
  line-height: var(--typography-heading-lineheight);
  white-space: pre-line;
  margin-block: var(--space-5) var(--space-8);
}
.studio01 .studio01-introduction {
  gap: var(--studio01-column-gap);
}
.studio01-introduction > p {
  flex: 1 1 55%;
  max-width: var(--content-width-narrow);
  font-size: var(--typography-lead-size);
  line-height: var(--typography-lead-lineheight);
  color: var(--text-secondary);
}
.studio01-introduction > div {
  flex: 0 1 35%;
  min-width: 0;
}
.studio01-availability {
  display: block;
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
  margin-block-end: var(--space-4);
  color: var(--text-muted);
}
.studio01-introduction .btn {
  white-space: normal;
}
.studio01-work {
  padding-block: var(--space-7) var(--studio01-section-gap);
  border-block-start: var(--border-width-thin) solid var(--border-default);
}
.studio01 .studio01-section-heading {
  gap: var(--space-5);
  margin-block-end: var(--space-6);
}
.studio01-section-heading h2 {
  font-size: var(--website-title-size);
  line-height: var(--line-height-tight);
  margin-block-start: var(--space-3);
}
.studio01-section-heading > span {
  font-size: var(--typography-caption-size);
  color: var(--text-muted);
}
.studio01 .studio01-projects {
  gap: var(--space-6);
}
.studio01-project {
  flex: 0 1 calc((100% - var(--space-6)) / 2);
  min-width: 0;
}
.studio01-project-media {
  overflow: hidden;
  border-radius: var(--media-radius);
}
.studio01-project-art {
  aspect-ratio: var(--media-aspect-video);
  min-height: calc(var(--space-4) * 14);
  padding: var(--space-6);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: var(--space-5);
  background: var(--brand-primary);
  color: var(--text-on-brand);
}
.studio01-project:nth-child(2n) .studio01-project-art {
  background: var(--surface-base);
  color: var(--text-primary);
}
.studio01-project-art > span {
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
}
.studio01-project-art > strong {
  font-family: var(--font-family-display);
  font-weight: var(--typography-heading-weight);
  font-size: var(--typography-product-title-size);
  line-height: var(--line-height-tight);
  letter-spacing: var(--letter-spacing-tight);
  white-space: pre-line;
}
.studio01 .studio01-project-meta {
  gap: var(--space-3);
  margin-block: var(--space-5) var(--space-3);
}
.studio01-project h3 {
  font-size: var(--font-size-xl);
  font-weight: var(--typography-heading-weight);
}
.studio01-project h3 a {
  text-decoration: none;
}
.studio01-project h3 a:hover {
  text-decoration: underline;
}
.studio01-project-meta > span {
  font-size: var(--typography-caption-size);
  color: var(--text-muted);
}
.studio01-project > p {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
  max-width: var(--content-width-narrow);
}
.studio01-approach {
  padding-block: var(--space-8) var(--studio01-section-gap);
  border-block-start: var(--border-width-thin) solid var(--border-default);
}
.studio01-approach > .flex,
.studio01-inquiry > .flex {
  gap: var(--studio01-column-gap);
}
.studio01-approach-intro {
  flex: 1 1 38%;
  min-width: 0;
}
.studio01-approach-intro h2,
.studio01-inquiry-intro h2 {
  font-size: var(--website-title-size);
  line-height: var(--line-height-tight);
  letter-spacing: var(--typography-heading-letterspacing);
  margin-block: var(--space-4) var(--space-5);
}
.studio01-approach-intro > p:last-child {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
}
.studio01-services {
  flex: 1 1 62%;
  min-width: 0;
}
.studio01-service-index {
  font-family: var(--font-family-mono);
  font-size: var(--typography-caption-size);
  color: var(--text-muted);
}
.studio01-services .accordion-content p,
.studio01-services ul {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
}
.studio01-services ul {
  padding-inline-start: var(--space-5);
  margin-block-start: var(--space-4);
}
.studio01-services li + li {
  margin-block-start: var(--space-2);
}
.studio01-inquiry {
  padding: var(--space-7);
  background: var(--surface-base);
  border-radius: var(--card-radius);
}
.studio01-inquiry-intro {
  flex: 1 1 42%;
  min-width: 0;
}
.studio01-inquiry-intro > p:not(.studio01-kicker) {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
}
.studio01 .studio01-location {
  margin-block-start: var(--space-8);
  color: var(--text-muted);
  font-size: var(--typography-caption-size);
}
.studio01-form {
  flex: 1 1 58%;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-5);
}
.studio01-name-row > .form-field {
  flex: 1 1 40%;
  min-width: 0;
}
.studio01-form .input,
.studio01-form .select,
.studio01-form .textarea {
  width: 100%;
}
.studio01-form .textarea {
  resize: vertical;
}
.studio01-form .form-field {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}
.studio01 .studio01-form-note {
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
}
.studio01-form-actions .btn {
  white-space: normal;
}
.studio01-form-actions > a {
  font-size: var(--typography-caption-size);
}
.studio01-feedback {
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
}
.studio01-feedback[role="alert"] {
  color: var(--color-danger);
}
.studio01-footer {
  margin-block-start: var(--studio01-section-gap);
  padding-block-start: var(--space-5);
  border-block-start: var(--border-width-thin) solid var(--border-default);
}
.studio01-footer > .flex {
  gap: var(--space-4);
  font-size: var(--typography-caption-size);
}
.studio01-footer > p {
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
  margin-block-start: var(--space-4);
}
.studio01 :is(h1, h2, h3, p, a, strong, span) {
  overflow-wrap: anywhere;
}
@media (max-width: 900px) {
  .studio01 {
    --studio01-column-gap: var(--space-7);
    padding-inline: var(--container-padding);
  }
  .studio01-approach > .flex,
  .studio01-inquiry > .flex {
    flex-direction: column;
  }
  .studio01-services,
  .studio01-form {
    width: 100%;
  }
}
@media (max-width: 600px) {
  .studio01 {
    padding-inline: var(--space-4);
  }
  .studio01 .studio01-introduction {
    flex-direction: column;
    align-items: start;
    gap: var(--space-5);
  }
  .studio01-project {
    flex-basis: 100%;
  }
  .studio01-project-art {
    padding: var(--space-5);
  }
  .studio01-inquiry {
    padding: var(--space-5);
  }
  .studio01-name-row > .form-field {
    flex-basis: 100%;
  }
  .studio01-hero {
    padding-block: var(--space-8);
  }
}
